var MAPDATA = {"W": 2048, "H": 1536, "marks": [{"name": "恓鸟城", "sub": "西部 · 山城军邦", "x": 0.137, "y": 0.825, "imp": 1, "desc": "西部大陆断脊山脉南段西侧内陆的核心城市，延西河流域重镇。别称“悲息之城”，冶铁业冠绝沧陆，兵器甲胄精良耐用。宗族长老制加卫国者庭军事制衡，战士信奉“以血作衣，以峰作干”。"}, {"name": "茹章城", "sub": "中部 · 神权霸主", "x": 0.521, "y": 0.304, "imp": 1, "desc": "中部平原、眸霞山脉东侧的核心都城级城市，中部文明的中心。沧陆公认最繁荣强大的城邦，疆域为诸邦之最。然而“永恒繁荣”以全城邦世代的寿命为代价——所有茹章人都活不过45岁。"}, {"name": "眴姚城", "sub": "东部 · 商贸港城", "x": 0.898, "y": 0.401, "imp": 1, "desc": "盎季地东侧沿海的港口城市，沧陆东部最大港口，苍瀛海航线核心枢纽。海商公会共治，风气开放，是全沧陆的信息交汇地与商品集散地。"}, {"name": "伏熏城", "sub": "南部 · 海岛民主之邦", "x": 0.1, "y": 0.8, "imp": 1, "desc": "伏熏岛中部腹地的核心城，伏熏岛屿文明的中心。政团民主制，十年换届选举；对外管控森严，外来商人只能在东部平安港活动。多数民众为无神论者。"}, {"name": "雁南岛", "sub": "西南 · 大陆型岛屿", "x": 0.24, "y": 0.68, "imp": 1, "desc": "承晚海峡南侧的大陆型岛屿，岛上分布有荻瑟湖，是西南海域的关键陆地节点。"}, {"name": "奇迤岛", "sub": "北部 · 大型岛屿", "x": 0.7, "y": 0.09, "imp": 1, "desc": "白绫海东北部的大型岛屿，位于斯瑜群岛西侧。扼根山、无昼碛均在此岛上。"}, {"name": "断脊山脉", "sub": "西部 · 主山脉", "x": 0.29, "y": 0.32, "desc": "西部大陆南北走向的主山脉，核心山脊海拔普遍在3000米以上，是西部地形的核心骨架，也是恓鸟城的精神图腾。北端延伸入海，南部为延西河发源地。"}, {"name": "眸霞山脉", "sub": "中部 · 分界线", "x": 0.4, "y": 0.3, "desc": "中部南北走向的主山脉，分隔西部内陆与中部平原，是沧陆最重要的地理分界线之一。全境观赏日落的最佳地点，被誉为“心的温柔乡”。"}, {"name": "自鸣山", "sub": "眸霞山脉 · 主峰", "x": 0.4, "y": 0.37, "imp": 1, "desc": "眸霞山脉主峰，海拔5243米，沧陆最高峰。黄昏时分霞光铺满山峦，色彩华丽绚烂，被世人称为“目遇之即为华丽之霞”。"}, {"name": "辞君山", "sub": "断脊山脉西北段", "x": 0.205, "y": 0.23, "desc": "海拔1437米。位于恓鸟城北部，山间云雾缭绕，半山处留有一处古亭悬址。是恓鸟城的文化符号，文人墨客的游历圣地。"}, {"name": "桓山", "sub": "白绫海南岸 · 山峰", "x": 0.48, "y": 0.12, "desc": "海拔4297米，被群山环抱，自古被视作祥瑞之地。民间流传“真龙降世”的传说，登顶者可向天许愿——但愿望从不会真正应验，登顶的人最终只会直面自身的执念。"}, {"name": "狩脊山", "sub": "伏熏岛 · 精神圣地", "x": 0.14, "y": 0.8, "desc": "海拔2136米，伏熏城人民瞻仰的精神圣地。山中遍植白色草木，象征一尘不染的圣洁——但极致的纯白只存在于传说与理想中。"}, {"name": "扼根山", "sub": "奇迤岛 · 隐秘圣地", "x": 0.63, "y": 0.07, "desc": "海拔1505米，奇迤岛西部绿洲中心，山体寸草不生。茹章城的隐秘信仰圣地——扼根山深处的灵祠里，沉睡着一具“不属于这个世界的神之遗骸”。"}, {"name": "无昼碛", "sub": "奇迤岛 · 秘境沙漠", "x": 0.72, "y": 0.11, "desc": "横贯奇迤岛中东部的反常沙漠，沙粒自带吸光特性，永远笼罩灰蒙暝色，无昼夜之分。神骸力量外泄扭曲光线与时空规则的产物。"}, {"name": "元荒海", "sub": "西界 · 外海", "x": 0.067, "y": 0.346, "desc": "地图最西侧的广阔外海，为西部大陆的西界海域。西境之外，是未知的浩瀚。"}, {"name": "白绫海", "sub": "北域 · 陆缘内海", "x": 0.363, "y": 0.085, "desc": "地图最北部的陆缘内海，被北部大陆、夺运岛环绕。北境水域辽阔，渔猎资源丰饶。"}, {"name": "肆星海", "sub": "中南部 · 核心海域", "x": 0.55, "y": 0.65, "desc": "地图中南部的核心主海域，位于中部大陆、盎季地与南部诸岛之间，是区域通航核心水域，多星礁。"}, {"name": "双生湾", "sub": "西部南段 · 海湾", "x": 0.1, "y": 0.79, "desc": "西部大陆南段的元荒海沿岸海湾，为延西河入海口所在区域。"}, {"name": "泊月湾", "sub": "中南部 · 海湾", "x": 0.52, "y": 0.52, "desc": "中部大陆南段的肆星海北岸海湾，为连奕江入海口所在区域。"}, {"name": "承晚海峡", "sub": "西南 · 水道", "x": 0.26, "y": 0.7, "desc": "分隔东生半岛与雁南岛的狭窄水道，连通元荒海与肆星海，为西南海域的通航咽喉。"}, {"name": "望暮大桥", "sub": "白绫海 · 巨型桥梁", "x": 0.6, "y": 0.2, "desc": "横跨白绫海南部海峡的巨型桥梁，连接中部大陆与奇迤岛，是跨区域核心交通枢纽。"}, {"name": "潜蛟海底隧道", "sub": "承晚海峡 · 工程", "x": 0.23, "y": 0.66, "desc": "穿越承晚海峡附近海域的海底隧道，连通北部陆块与雁南岛，与望暮大桥并称沧陆两大跨海工程。"}, {"name": "吴阳湖", "sub": "中东部 · 淡水湖", "x": 0.64, "y": 0.37, "desc": "中东部平原的大型淡水湖，坐落于连奕江下游东侧。盛夏“灼月”为农忙收割期。"}, {"name": "荻瑟湖", "sub": "雁南岛 · 湖泊", "x": 0.27, "y": 0.7, "desc": "雁南岛内部的天然湖泊，为岛上核心水域。"}, {"name": "延西河", "sub": "西部 · 河流", "x": 0.19, "y": 0.6, "desc": "发源于断脊山脉，向南流经西部内陆，注入双生湾附近海域。"}, {"name": "连奕江", "sub": "中部 · 河流", "x": 0.56, "y": 0.45, "desc": "发源于眸霞山脉，向东横贯中部平原，流经吴阳湖周边，最终注入泊月湾附近海域。"}, {"name": "屈海", "sub": "东南 · 海湾", "x": 0.84, "y": 0.46, "desc": "东部大陆南段被东枝崖环绕包裹的海湾。"}, {"name": "东枝崖", "sub": "东南 · 崖岸海角", "x": 0.87, "y": 0.48, "desc": "盎季地最南端的崖岸海角，是大陆向肆星海延伸的最南端区域。"}, {"name": "斯瑜群岛", "sub": "东北 · 群岛", "x": 0.9, "y": 0.16, "desc": "白绫海东侧与苍瀛海西侧交界处的小型群岛，扼两海通航之要冲。"}, {"name": "南引群岛", "sub": "肆星海东南 · 火山群岛", "x": 0.91, "y": 0.86, "desc": "地处肆星海东南端的大型火山型群岛，岛屿星罗，火山地貌显著。"}, {"name": "归尘屿", "sub": "肆星海南部 · 星礁岛", "x": 0.69, "y": 0.7, "desc": "肆星海南部、盎季地正南方的连片星礁型海岛。"}, {"name": "赎誓阁", "sub": "肆星海南 · 岛屿", "x": 0.62, "y": 0.81, "desc": "肆星海南偏的岛屿，是东南海域的关键陆地节点。"}, {"name": "星沙礁", "sub": "肆星海 · 暗礁群", "x": 0.55, "y": 0.8, "desc": "肆星海南部的大片浅滩/暗星礁群，散布于中部海域，为航行之险地。"}], "rivers": [{"pts": [[0.31, 0.5], [0.28, 0.55], [0.24, 0.6], [0.19, 0.66], [0.15, 0.71], [0.12, 0.76], [0.1, 0.79]], "name": "延西河"}, {"pts": [[0.41, 0.42], [0.46, 0.43], [0.52, 0.42], [0.58, 0.41], [0.62, 0.43], [0.63, 0.46], [0.6, 0.49], [0.55, 0.51], [0.53, 0.52]], "name": "连奕江"}], "lakes": [{"x": 0.64, "y": 0.37, "r": 0.022, "name": "吴阳湖"}, {"x": 0.27, "y": 0.7, "r": 0.014, "name": "荻瑟湖"}]};

